const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

// wait(ms, label) を書く

// async function main() { ... }

// main() を呼び、直後に「呼び出し後」を出す

quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

function wait(ms, label) {
  return new Promise((resolve) => setTimeout(() => resolve(label), ms));
}

async function main() {
  console.log("開始");
  for (const line of lines) {
    const [ms, label] = line.split(" ");
    const v = await wait(Number(ms), label);
    console.log("受け取った:", v);
  }
  console.log("終了");
}
main();
console.log("呼び出し後");

