// async / await で全員の点数を足し、「合計: 数値」を出す

quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

const SCORES = { tanaka: 80, suzuki: 65, sato: 92, kato: 0 };
function getScore(name) {
  return new Promise((resolve) => setTimeout(() => resolve(SCORES[name]), 10));
}

async function main() {
  let total = 0;
  for (const name of lines) {
    total += await getScore(name);
  }
  console.log(`合計: ${total}`);
}
main();
